{
  "name": "truth-lens",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "api": "node apps/api/src/server.ts",
    "worker": "node apps/worker/src/worker.ts",
    "run": "node apps/worker/src/worker.ts && node apps/api/src/server.ts"
  }
}

import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(process.env.HOME || '.', 'projects', 'truth-lens');
const DATA_DIR = path.join(ROOT, 'data');
const POSTS_DIR = path.join(DATA_DIR, 'posts');
const ANALYSIS_DIR = path.join(DATA_DIR, 'analysis');

function ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function writeJson(file, value) {
  fs.writeFileSync(file, JSON.stringify(value, null, 2));
}

export function savePost(post) {
  ensureDir(POSTS_DIR);
  const file = path.join(POSTS_DIR, `${post.id}.json`);
  writeJson(file, post);
}

export function getPost(id) {
  const file = path.join(POSTS_DIR, `${id}.json`);
  if (!fs.existsSync(file)) return null;
  return readJson(file);
}

export function listPosts() {
  ensureDir(POSTS_DIR);
  return fs.readdirSync(POSTS_DIR)
    .filter((f) => f.endsWith('.json'))
    .sort()
    .map((f) => readJson(path.join(POSTS_DIR, f)));
}

export function saveAnalysis(result) {
  ensureDir(ANALYSIS_DIR);
  const file = path.join(ANALYSIS_DIR, `${result.id}.json`);
  writeJson(file, result);
}

export function getAnalysis(id) {
  const file = path.join(ANALYSIS_DIR, `${id}.json`);
  if (!fs.existsSync(file)) return null;
  return readJson(file);
}

export function listAnalysis() {
  ensureDir(ANALYSIS_DIR);
  return fs.readdirSync(ANALYSIS_DIR)
    .filter((f) => f.endsWith('.json'))
    .sort()
    .map((f) => readJson(path.join(ANALYSIS_DIR, f)));
}

export async function fetchSubredditNew(subreddit) {
  const now = new Date().toISOString();
  return [
    {
      id: `demo-${subreddit}-1`,
      subreddit,
      author: 'demo_user_alpha',
      title: `A discussion thread in r/${subreddit}`,
      body: `I think people are overreacting. We should take a balanced view and consider all sides carefully. This may be more coordinated than it seems.`,
      created_at: now,
      permalink: `/r/${subreddit}/comments/demo-${subreddit}-1`
    },
    {
      id: `demo-${subreddit}-2`,
      subreddit,
      author: 'demo_user_beta',
      title: `Another thread in r/${subreddit}`,
      body: `Everyone knows this is manipulated. Clearly the whole thing is compromised and nobody can trust it anymore.`,
      created_at: now,
      permalink: `/r/${subreddit}/comments/demo-${subreddit}-2`
    }
  ];
}

const CERTAINTY_WORDS = ['clearly', 'obviously', 'definitely', 'undoubtedly', 'everyone knows'];
const HEDGE_WORDS = ['maybe', 'perhaps', 'might', 'seems', 'likely'];
const EMPATHY_WORDS = ['i understand', 'that must be hard', 'it makes sense'];
const CONSENSUS_WORDS = ['everyone knows', 'nobody can trust', 'the whole thing', 'all sides'];

function countMatches(text, patterns) {
  const lower = text.toLowerCase();
  return patterns.reduce((sum, p) => sum + (lower.includes(p) ? 1 : 0), 0);
}

function tokenize(text) {
  return text.toLowerCase().split(/[^a-z0-9']+/).filter(Boolean);
}

export function extractContentFeatures(post) {
  const text = `${post.title || ''} ${post.body || ''}`.trim();
  const tokens = tokenize(text);
  const unique = new Set(tokens);
  const sentences = text.split(/[.!?]+/).map((s) => s.trim()).filter(Boolean);
  const sentenceLengths = sentences.map((s) => tokenize(s).length);
  const meanSentenceLength = sentenceLengths.length
    ? sentenceLengths.reduce((a, b) => a + b, 0) / sentenceLengths.length
    : 0;

  return {
    id: post.id,
    subreddit: post.subreddit,
    token_count: tokens.length,
    sentence_count: sentences.length,
    lexical_diversity: tokens.length ? unique.size / tokens.length : 0,
    certainty_marker_count: countMatches(text, CERTAINTY_WORDS),
    hedging_marker_count: countMatches(text, HEDGE_WORDS),
    empathy_marker_count: countMatches(text, EMPATHY_WORDS),
    consensus_marker_count: countMatches(text, CONSENSUS_WORDS),
    self_reference_count: (text.match(/\b(i|me|my|mine)\b/gi) || []).length,
    exclamation_count: (text.match(/!/g) || []).length,
    question_count: (text.match(/\?/g) || []).length,
    mean_sentence_length: Number(meanSentenceLength.toFixed(2)),
    abstraction_hint: countMatches(text, ['system', 'structure', 'narrative', 'context', 'coordinated', 'manipulated', 'compromised'])
  };
}

export function scoreContent(post, features) {
  let synthetic = 0;
  let steering = 0;
  let coordination = 0;
  const reasons = [];

  if (features.lexical_diversity < 0.72) {
    synthetic += 0.12;
    reasons.push('lower lexical diversity');
  }

  if (features.mean_sentence_length > 12) {
    synthetic += 0.1;
    reasons.push('long polished sentences');
  }

  if (features.certainty_marker_count > 0) {
    steering += 0.2;
    reasons.push('certainty markers');
  }

  if (features.consensus_marker_count > 0) {
    steering += 0.25;
    coordination += 0.15;
    reasons.push('consensus framing');
  }

  if (features.abstraction_hint > 1) {
    synthetic += 0.12;
    steering += 0.12;
    reasons.push('abstraction-heavy language');
  }

  if (features.exclamation_count > 1) {
    steering += 0.08;
    reasons.push('elevated emotional punctuation');
  }

  synthetic = clamp(synthetic + 0.18);
  steering = clamp(steering + 0.12);
  coordination = clamp(coordination + 0.1);

  const confidence = clamp(0.25 + (features.token_count > 12 ? 0.2 : 0) + (reasons.length * 0.08));

  return {
    id: post.id,
    entity_type: 'content',
    synthetic_language_likelihood: round2(synthetic),
    narrative_steering_likelihood: round2(steering),
    coordination_likelihood: round2(coordination),
    confidence: round2(confidence),
    confidence_band: band(confidence),
    reasons: Array.from(new Set(reasons))
  };
}

function clamp(n) {
  return Math.max(0, Math.min(1, n));
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

function band(n) {
  if (n < 0.2) return 'very_low';
  if (n < 0.4) return 'low';
  if (n < 0.6) return 'moderate';
  if (n < 0.8) return 'high';
  return 'very_high';
}

import { fetchSubredditNew } from '../../../packages/reddit/src/fetch.ts';
import { extractContentFeatures } from '../../../packages/features/src/index.js';
import { scoreContent } from '../../../packages/scoring/src/index.js';
import { savePost, saveAnalysis } from '../../../packages/storage/src/storage.js';

const SUBS = (process.env.PILOT_SUBREDDITS ?? 'technology,news,gaming')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

async function main() {
  console.log('Truth Lens worker started');
  console.log('Pilot subreddits:', SUBS.join(', '));

  for (const subreddit of SUBS) {
    const posts = await fetchSubredditNew(subreddit);

    for (const post of posts) {
      savePost(post);
      const features = extractContentFeatures(post);
      const score = scoreContent(post, features);

      saveAnalysis({
        id: post.id,
        post,
        features,
        score,
        analyzed_at: new Date().toISOString()
      });

      console.log(`[saved] ${post.id}`);
      console.log(`[scored] ${post.id} synthetic=${score.synthetic_language_likelihood} steering=${score.narrative_steering_likelihood} coordination=${score.coordination_likelihood}`);
    }
  }

  console.log('Worker cycle complete');
}

main().catch((err) => {
  console.error('Worker failed:', err);
  process.exit(1);
});

import http from 'node:http';
import { listPosts, getPost, listAnalysis, getAnalysis } from '../../../packages/storage/src/storage.js';

const PORT = Number(process.env.API_PORT ?? 3001);

function json(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data, null, 2));
}

function notFound(res) {
  return json(res, 404, { error: 'not_found' });
}

function summarize(analysisItems) {
  const total = analysisItems.length;
  const avgSynthetic = total ? analysisItems.reduce((a, x) => a + (x.score.synthetic_language_likelihood || 0), 0) / total : 0;
  const avgSteering = total ? analysisItems.reduce((a, x) => a + (x.score.narrative_steering_likelihood || 0), 0) / total : 0;
  const avgCoordination = total ? analysisItems.reduce((a, x) => a + (x.score.coordination_likelihood || 0), 0) / total : 0;

  const topFlagged = [...analysisItems]
    .sort((a, b) => (b.score.narrative_steering_likelihood + b.score.coordination_likelihood) - (a.score.narrative_steering_likelihood + a.score.coordination_likelihood))
    .slice(0, 5)
    .map((x) => ({
      id: x.id,
      subreddit: x.post.subreddit,
      author: x.post.author,
      score: x.score,
      reasons: x.score.reasons
    }));

  return {
    total_posts: total,
    average_synthetic_language_likelihood: round2(avgSynthetic),
    average_narrative_steering_likelihood: round2(avgSteering),
    average_coordination_likelihood: round2(avgCoordination),
    top_flagged: topFlagged
  };
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '/', 'http://localhost');
  const parts = url.pathname.split('/').filter(Boolean);

  if (url.pathname === '/health') {
    return json(res, 200, {
      status: 'ok',
      service: 'truth-lens-api',
      time_utc: new Date().toISOString(),
      version: 'v1'
    });
  }

  if (url.pathname === '/posts') {
    return json(res, 200, listPosts());
  }

  if (parts[0] === 'posts' && parts[1]) {
    const post = getPost(parts[1]);
    return post ? json(res, 200, post) : notFound(res);
  }

  if (url.pathname === '/analysis') {
    return json(res, 200, listAnalysis());
  }

  if (parts[0] === 'analysis' && parts[1]) {
    const analysis = getAnalysis(parts[1]);
    return analysis ? json(res, 200, analysis) : notFound(res);
  }

  if (url.pathname === '/summary') {
    return json(res, 200, summarize(listAnalysis()));
  }

  return json(res, 200, {
    message: 'truth-lens api',
    routes: ['/health', '/posts', '/posts/:id', '/analysis', '/analysis/:id', '/summary']
  });
});

server.listen(PORT, () => {
  console.log(`Truth Lens API running on port ${PORT}`);
});
